function [Ksr,Ksc,Ksv,Fsr,Fsv,fc,kc] = AssembleSparseConPen_FR(iele,nnpe,np,numind,eqv,ke,fe,Ksr,Ksc,Ksv,Fsr,Fsv,fc,kc)%%  Called by FitOrientationData2FR%% assembles elemental RHS and LHS (stiffness) matrices into global counterparts% assuming sparse matrices    for  i=1:nnpe              ii = np(iele,i);         if(ii>numind)        ieqv = ii - numind;        ii = eqv(2,ieqv);        end          Fsr(fc)=ii;         Fsv(fc)=fe(i);         fc=fc+1;                      for j=1:nnpe                        jj=np(iele,j);	               if(jj>numind)               jeqv = jj - numind;               jj = eqv(2,jeqv);               end                        Ksr(kc)=ii;             Ksc(kc)=jj;             Ksv(kc)=ke(i,j);             kc=kc+1;                   end    end